// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint64 amount, uint64 delay) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        uint256 warpTo = 1_000_000;
        vm.warp(warpTo);
        uint256 unlockTime = warpTo + delay;
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint256 accUnlockTime, ) = c.Acc(actor);
        assertTrue(accUnlockTime >= warpTo);
    }
}
